 "content": "def _runs(values, color):
    result = []
    start = None
    for i, value in enumerate(values + [None]):
        if value == color:
            if start is None:
                start = i
        elif start is not None:
            result.append((start, i))
            start = None
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    pairs = []
    for color in counts:
        if color == bg:
            continue
        for a, b in _runs(grid[0], color):
            for c, d in _runs(grid[-1], color):
                if b - a == d - c:
                    pairs.append((color, a, b, c, d))
    if not pairs:
        return out
    frame, top_a, top_b, bot_a, bot_b = max(pairs, key=lambda p: p[2] - p[1])
    other = [v for v in counts if v not in (bg, frame)]
    markers = set(other)

    # Extend the top and bottom bars inward along their columns. A clue cell
    # becomes the emphasized endpoint (4) and halts that ray.
    for col in range(top_a, top_b):
        for r in range(1, h):
            value = grid[r][col]
            if value in markers:
                out[r][col] = 4
                break
            if value == bg:
                out[r][col] = 9
    for col in range(bot_a, bot_b):
        for r in range(h - 2, -1, -1):
            value = grid[r][col]
            if value in markers:
                out[r][col] = 4
                break
            if value == bg:
                out[r][col] = 9
    return out


