def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Find equal-length runs of one color on opposing borders.
    candidates = []
    for color in counts:
        if color == background:
            continue
        for a, b in _runs(grid[0], color):
            for c, d in _runs(grid[-1], color):
                if b - a == d - c:
                    candidates.append((b-a, 'horizontal', color, a, b, c, d))
        left = [grid[r][0] for r in range(h)]
        right = [grid[r][-1] for r in range(h)]
        for a, b in _runs(left, color):
            for c, d in _runs(right, color):
                if b - a == d - c:
                    candidates.append((b-a, 'vertical', color, a, b, c, d))
    if not candidates:
        return [row[:] for row in grid]
    _, axis, frame, first_a, first_b, second_a, second_b = max(candidates)

    clue_colors = [value for value in counts if value not in (background, frame)]
    if not clue_colors:
        return [row[:] for row in grid]
    clue_color = min(clue_colors, key=lambda value: counts[value])
    out = [row[:] for row in grid]
    clues = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == clue_color]

    def paint(r, c):
        if grid[r][c] == background:
            out[r][c] = clue_color

    if axis == 'horizontal':
        # First run is the top bar, second the bottom bar. A clue in a bar's
        # column-span sends a ray toward that bar and projects its offset onto
        # the corresponding column of the opposite bar, through the grid.
        for r, col in clues:
            if first_a <= col < first_b:
                out[r][col] = 4
                for rr in range(r-1, 0, -1):
                    paint(rr, col)
                target = second_a + (col - first_a)
                for rr in range(h):
                    paint(rr, target)
            elif second_a <= col < second_b:
                out[r][col] = 4
                for rr in range(r+1, h-1):
                    paint(rr, col)
                target = first_a + (col - second_a)
                for rr in range(h):
                    paint(rr, target)
    else:
        # Transposed version for matching left/right border runs.
        for r, col in clues:
            if first_a <= r < first_b:
                out[r][col] = 4
                for cc in range(col-1, 0, -1):
                    paint(r, cc)
                target = second_a + (r - first_a)
                for cc in range(w):
                    paint(target, cc)
            elif second_a <= r < second_b:
                out[r][col] = 4
                for cc in range(col+1, w-1):
                    paint(r, cc)
                target = first_a + (r - second_a)
                for cc in range(w):
