def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Find equal-length runs of one color on opposing borders.
    candidates = []
    for color in counts:
        if color == background:
            continue
        for a, b in _runs(grid[0], color):
            for c, d in _runs(grid[-1], color):
                if b - a == d - c:
                    candidates.append((b - a, 'horizontal', color, a, b, c, d))
        left = [grid[r][0] for r in range(h)]
        right = [grid[r][-1] for r in range(h)]
        for a, b in _runs(left, color):
            for c, d in _runs(right, color):
                if b - a == d - c:
                    candidates.append((b - a, 'vertical', color, a, b, c, d))
    if not candidates:
        return out

    _, orientation, bar_color, a, b, c, d = max(candidates)
    clue_colors = [value for value in counts if value not in (background, bar_color)]
    if not clue_colors:
        return out
    fill_color = min(clue_colors, key=lambda value: counts[value])

    def cast(r, col, dr, dc):
        r += dr
        col += dc
        while 0 <= r < h and 0 <= col < w:
            value = grid[r][col]
            if value == background:
                out[r][col] = fill_color
            elif value != bar_color:
                out[r][col] = 4
                break
            r += dr
            col += dc

    if orientation == 'horizontal':
        # Cast inward from each top/bottom bar cell.
        for col in range(a, b):
            cast(0, col, 1, 0)
        for col in range(c, d):
            cast(h - 1, col, -1, 0)
    else:
        # Transposed version for left/right bars.
        for r in range(a, b):
            cast(r, 0, 0, 1)
        for r in range(c, d):
            cast(r, w - 1, 0, -1)
    return out


