    result, start = [], None
    for i, value in enumerate(values + [None]):
        if value == color and start is None:
            start = i
        elif value != color and start is not None:
            result.append((start, i))
            start = None
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    border_counts = {}
    for r in range(h):
        for c in range(w):
            if r in (0, h - 1) or c in (0, w - 1):
                value = grid[r][c]
                if value != background:
                    border_counts[value] = border_counts.get(value, 0) + 1
    if not border_counts:
        return [row[:] for row in grid]
    bar = max(border_counts, key=border_counts.get)
    clue_colors = [v for v in counts if v not in (background, bar)]
    if not clue_colors:
        return [row[:] for row in grid]
    clue = min(clue_colors, key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # Pair same-color border runs on opposing edges. If their lengths differ
    # by one, align their far endpoints; this handles the slightly offset rails.
    pairs = []
    for orientation, seq_a, seq_b in (
        ('v', grid[0], grid[-1]),
        ('h', [grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)]),
    ):
        for run_a in _runs(seq_a, bar):
            for run_b in _runs(seq_b, bar):
                if abs((run_a[1] - run_a[0]) - (run_b[1] - run_b[0])) <= 1:
                    pairs.append((orientation, run_a, run_b))

    for orientation, run_a, run_b in pairs:
        length_a = run_a[1] - run_a[0]
        length_b = run_b[1] - run_b[0]
        for source, opposite, edge_side in (
            (run_a, run_b, 'first'),
            (run_b, run_a, 'second'),
        ):
            start, end = source
            other_start, other_end = opposite
            source_len = end - start
            other_len = other_end - other_start
            # When rails differ by one, line up their terminal endpoints.
            shift = source_len - other_len
            def mapped(index):
                if shift > 0:
                    return other_start + index - shift
                return other_start + index

            if orientation == 'v':
                is_top = edge_side == 'first'
                dr = -1 if is_top else 1
                clue_cells = [(r, c) for r in range(1, h - 1)
                              for c in range(start, end) if grid[r][c] == clue]
                for r, c in clue_cells:
                    out[r][c] = 4
                    rr = r + dr
                    while 0 <= rr < h and grid[rr][c] == background:
                        out[rr][c] = clue
                        rr += dr
                    offset = c - start
                    target_c = mapped(offset)
                    if 0 <= target_c < w:
                        for rr in range(1, h - 1):
                            if grid[rr][target_c] == background:
                                out[rr][target_c] = clue
            else:
                is_left = edge_side == 'first'
                dc = -1 if is_left else 1
                clue_cells = [(r, c) for r in range(start, end)
                              for c in range(1, w - 1) if grid[r][c] == clue]
                for r, c in clue_cells:
                    out[r][c] = 4
                    cc = c + dc
                    while 0 <= cc < w and grid[r][cc] == background:
                        out[r][cc] = clue
                        cc += dc
                    offset = r - start
                    target_r = mapped(offset)
                    if 0 <= target_r < h:
                        for cc in range(1, w - 1):
                            if grid[target_r][cc] == background:
                                out[target_r][cc] = clue
    return out


